import {layouts,defaultLayout} from './layouts.js';
import {escapeHtml as esc} from './engine.js';
export const clone=value=>JSON.parse(JSON.stringify(value));
export const uid=()=>`item-${globalThis.crypto.randomUUID().slice(0,12)}`;
export function safeUrl(value, image=false){const s=String(value||'').trim();if(!s)return '';if(!image&&/^\/(?!\/)[^\s<>]*$/.test(s))return s;try{const url=new URL(s);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?s:'';}catch{return '';}}
export function newEntry(kind,l='pl'){const pl=l==='pl';return {id:uid(),kind,title:pl?(kind==='product'?'Nowa oferta':kind==='page'?'Nowa strona':'Nowy artykuł'):(kind==='product'?'New offer':kind==='page'?'New page':'New article'),slug:'',excerpt:'',body:'',image:'',alt:'',category:'',author:'',price:'',url:'',published:true};}
export function createProject(t,l='pl',old={}){const pl=l==='pl';return {schema:1,themeId:t.id,language:l,siteLayout:defaultLayout(t.id),brand:old.brand||t.name,email:old.email||'hello@example.com',accent:old.accent||t.accent,font:old.font||t.font,background:t.bg,ink:['tech','automotive','portfolio'].includes(t.layout)?'#f5f5f1':'#22251f',radius:0,width:1240,fontSize:16,heroTitle:t.headline[l],heroText:t.description[l],heroImage:t.image,heroAlt:t.topic[l],heroLabel:t.topic[l],heroButton:pl?'Odkrywaj':'Explore',heroTarget:'article',showHero:true,showPosts:true,postsTitle:pl?'Najnowsze historie':'Latest stories',footer:pl?'Tworzone z pasją.':'Made with care.',errorTitle:pl?'Ta strona nie istnieje.':'This page does not exist.',errorText:pl?'Wróć na stronę główną i odkryj więcej.':'Return home and discover more.',entries:[{...newEntry('article',l),id:'article',slug:'article',title:t.article[l],excerpt:t.description[l],body:pl?'## Nowa perspektywa\n\nKażda historia zaczyna się od pomysłu. Tutaj możesz opowiedzieć własną.\n\n**Zacznij od tego, co jest dla Ciebie ważne.**':'## A fresh perspective\n\nEvery story starts with an idea. Tell your own here.\n\n**Start with what matters to you.**',image:t.image,alt:t.topic[l],category:t.topic[l],author:old.brand||t.name},{...newEntry('product',l),id:'product',slug:'product',title:pl?'Poznaj naszą ofertę':'Explore our offer',excerpt:t.description[l],body:pl?'## Szczegóły\n\nOpisz produkt lub usługę, warianty i warunki.':'## Details\n\nDescribe the product or service, options and terms.',price:pl?'Wycena indywidualna':'Price on request',image:t.image,alt:t.topic[l],category:t.topic[l]},{...newEntry('page',l),id:'about',slug:'about',title:pl?'O nas':'About',excerpt:t.description[l],body:pl?'## Nasza historia\n\nTworzymy miejsce dla ludzi, którzy cenią jakość i świadome wybory. Opowiedz tutaj o swojej marce.':'## Our story\n\nWe create a place for people who value quality and thoughtful choices. Tell your brand story here.',image:t.image,alt:t.topic[l]},{...newEntry('page',l),id:'contact',slug:'contact',title:pl?'Porozmawiajmy.':'Let’s talk.',body:pl?'Masz pytanie lub pomysł na współpracę? Napisz do nas.':'Have a question or collaboration in mind? Get in touch.'}],sections:[],menu:[{id:'nav-home',label:pl?'Start':'Home',target:'home',url:''},{id:'nav-article',label:pl?'Artykuły':'Journal',target:'article',url:''},{id:'nav-about',label:pl?'O nas':'About',target:'about',url:''},{id:'nav-contact',label:pl?'Kontakt':'Contact',target:'contact',url:''}]};}
const textKeys=['brand','email','heroTitle','heroText','heroImage','heroAlt','heroLabel','heroButton','heroTarget','postsTitle','footer','errorTitle','errorText'];
const entryKeys=['id','kind','title','slug','excerpt','body','image','alt','category','author','price','url'];
export function validateProject(value,themeId){if(!value||value.schema!==1||value.themeId!==themeId||!['pl','en'].includes(value.language))throw new Error('Invalid project / Nieprawidłowy projekt');const selected=value.siteLayout??defaultLayout(themeId);if(!Object.hasOwn(layouts,selected))throw new Error('Invalid layout');const p={schema:1,themeId,language:value.language,siteLayout:selected};for(const key of textKeys){if(typeof value[key]!=='string'||value[key].length>30000)throw new Error('Invalid field: '+key);p[key]=value[key];}for(const key of ['accent','background','ink']){if(!/^#[a-f0-9]{6}$/i.test(value[key]))throw new Error('Invalid color');p[key]=value[key];}if(!['serif','sans'].includes(value.font))throw new Error('Invalid font');p.font=value.font;for(const [key,min,max] of [['radius',0,40],['width',900,1500],['fontSize',14,24]]){if(!Number.isFinite(value[key])||value[key]<min||value[key]>max)throw new Error('Invalid style');p[key]=value[key];}for(const key of ['showHero','showPosts']){if(typeof value[key]!=='boolean')throw new Error('Invalid visibility');p[key]=value[key];}if(!Array.isArray(value.entries)||value.entries.length>100||!Array.isArray(value.sections)||value.sections.length>30||!Array.isArray(value.menu)||value.menu.length>20)throw new Error('Project limits exceeded');const ids=new Set(['home','404']);p.entries=value.entries.map(row=>{const r={};for(const key of entryKeys){if(typeof row[key]!=='string'||row[key].length>100000)throw new Error('Invalid entry');r[key]=row[key];}if(!/^[a-z0-9-]+$/.test(r.id)||ids.has(r.id)||!['article','product','page'].includes(r.kind)||typeof row.published!=='boolean')throw new Error('Invalid entry ID or type');ids.add(r.id);r.published=row.published;return r;});const sectionIds=new Set();p.sections=value.sections.map(row=>{if(!row||!['text','image','cta'].includes(row.type)||!/^item-[a-z0-9-]+$/.test(row.id)||sectionIds.has(row.id))throw new Error('Invalid section');sectionIds.add(row.id);const r={type:row.type,id:row.id};for(const k of ['title','body','image','alt','button','url']){if(typeof row[k]!=='string'||row[k].length>100000)throw new Error('Invalid section field');r[k]=row[k];}return r;});p.menu=value.menu.map(row=>{const r={};for(const key of ['id','label','target','url']){if(typeof row?.[key]!=='string'||row[key].length>500)throw new Error('Invalid menu');r[key]=row[key];}return r;});return p;}
export function slugFor(entry){return (entry.slug||entry.id).toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/ł/g,'l').replace(/[^a-z0-9-]/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').slice(0,80)||entry.id;}
export function entryPath(entry){return `${entry.kind==='page'?'pages':'content'}/${entry.id}.html`;}
export function entryUrl(entry){return safeUrl(entry.url)||(entry.kind==='page'?`/p/${slugFor(entry)}.html`:`/search?q=${encodeURIComponent(entry.title)}`);}
export function inlineText(value){return esc(value).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');}
export function richText(value){let list=false;const out=[];for(const line of String(value).split('\n')){if(line.startsWith('- ')){if(!list){out.push('<ul>');list=true;}out.push(`<li>${inlineText(line.slice(2))}</li>`);continue;}if(list){out.push('</ul>');list=false;}if(!line.trim())continue;if(line.startsWith('## '))out.push(`<h2>${inlineText(line.slice(3))}</h2>`);else if(line.startsWith('> '))out.push(`<blockquote>${inlineText(line.slice(2))}</blockquote>`);else out.push(`<p>${inlineText(line)}</p>`);}if(list)out.push('</ul>');return out.join('');}
export class History{constructor(limit=40){this.past=[];this.future=[];this.limit=limit;}remember(value){this.past.push(clone(value));if(this.past.length>this.limit)this.past.shift();this.future=[];}undo(current){if(!this.past.length)return null;this.future.push(clone(current));return this.past.pop();}redo(current){if(!this.future.length)return null;this.past.push(clone(current));return this.future.pop();}}
